  Hypothesis Csv : rdn SEGS M (Z_to_bv 64 (SSP.ls_sev L)) 4 = Some (Z_to_le_bytes 4 sv).
  Hypothesis Rsv : (0 <= sv < 2 ^ 32)%Z.
  Hypothesis IMG : forall i, (SSP.ls_img_lo L <= i < SSP.ls_img_hi L)%Z -> M (Z_to_bv 64 i) = None.
